(function(root){
'use strict';
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=x=>String(x||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
function inspect(data){return data.pages.map(p=>{const text=plain(p.html);const issues=[];if(!p.title?.trim())issues.push('补充明确标题');if(text.length<80)issues.push('补充产品用途、参数或服务说明');if(!p.summary?.trim())issues.push('补充页面摘要');if(!/<h[23][\s>]/i.test(p.html||''))issues.push('用小标题组织内容');if(!/https:\/\//i.test(p.html||''))issues.push('核对事实依据，按需添加来源链接');return {...p,text,issues};});}
function render(data){const rows=inspect(data),good=rows.filter(p=>!p.issues.length).length,observations=data.observations||[];
return `<div class="insights geo-workspace"><section class="card"><div class="insight-heading"><div><h2>GEO 优化</h2><p>让 AI 搜索更容易理解和引用真实的网站内容。</p></div><button data-action="geoRefresh">重新检查草稿</button></div><p class="small muted">检查当前网站草稿；收录、引用和访问另行观察。内容检查通过不保证被收录、推荐或获得排名。</p></section><div class="insight-metrics"><article class="card insight-metric"><span>检查页面</span><strong>${rows.length}</strong><small>当前网站草稿</small></article><article class="card insight-metric"><span>需要完善</span><strong>${rows.length-good}</strong><small>按页面逐项处理</small></article><article class="card insight-metric"><span>AI 引用观察</span><strong>${observations.length}</strong><small>人工记录，非全网统计</small></article><article class="card insight-metric"><span>AI 来源访问</span><strong>—</strong><small>访问统计尚未接入</small></article></div><section class="card"><h3>企业与内容准备</h3><div class="insight-list"><div><span><strong>企业身份</strong><small>${e(data.name||'尚未填写企业名称')}</small></span><span class="tag">${data.name?'已有资料':'待完善'}</span></div><div><span><strong>产品或服务</strong><small>${e(data.product||'尚未填写产品说明')}</small></span><button data-action="navigate" data-page="website-articles">用智能软文补充内容</button></div></div><p>组织结构化数据随正式网站页面输出；内容必须与页面上可见信息一致。不生成虚假评价、认证或问答。</p></section><section class="card"><h3>页面改进清单</h3><div class="table-scroll"><table><thead><tr><th>页面</th><th>需要处理</th><th>操作</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${e(p.title)}</td><td>${p.issues.length?p.issues.map(e).join('；'):'基础内容检查通过，仍需人工核对事实'}</td><td><button data-action="geoEdit" data-id="${e(p.id)}">编辑详情</button></td></tr>`).join('')||'<tr><td colspan="3">暂无页面，请先添加网站内容。</td></tr>'}</tbody></table></div></section><section class="card"><h3>公开站点与 AI 引用</h3><div class="table-scroll"><table><thead><tr><th>项目</th><th>状态</th><th>核对方式</th></tr></thead><tbody><tr><td>公开访问、robots 与收录</td><td>未检查</td><td>网站发布后核对公开地址与站长平台</td></tr><tr><td>结构化数据</td><td>正式页面自动输出企业身份</td><td>与可见企业名称核对；不代表获准展示</td></tr><tr><td>AI 回答引用</td><td>人工观察</td><td>记录引擎、问题、日期、地区与引用网址</td></tr></tbody></table></div><form data-form="geoSave" class="field-grid"><label>AI 引擎<input name="engine" required maxlength="80" placeholder="例如：Google AI Mode / ChatGPT"></label><label>观察日期<input type="date" name="date" required></label><label>提问内容<input name="question" required maxlength="500"></label><label>地区 / 语言<input name="market" maxlength="120"></label><label>是否引用本站<select name="cited"><option value="unknown">未确认</option><option value="yes">已看到引用</option><option value="no">本次未看到</option></select></label><label>引用或证据网址<input type="url" name="url" maxlength="2000" placeholder="https://"></label><label class="span2">回答摘录 / 证据说明<textarea name="note" rows="2" maxlength="3000"></textarea></label><div class="span2 page-actions"><button class="primary">保存观察记录</button></div></form><div class="table-scroll"><table><thead><tr><th>日期 / 引擎</th><th>问题与地区</th><th>观察结果</th><th>证据</th></tr></thead><tbody>${observations.map(o=>`<tr><td>${e(o.date)} · ${e(o.engine)}</td><td>${e(o.question)}<br>${e(o.market)}</td><td>${e(({yes:'已看到引用',no:'本次未看到',unknown:'未确认'})[o.cited])}</td><td>${e(o.url)}<br>${e(o.note)}</td></tr>`).join('')||'<tr><td colspan="4">暂无观察记录。单次回答不代表整体排名或持续引用。</td></tr>'}</tbody></table></div></section><p class="small muted">参考：<a href="https://developers.google.com/search/docs/appearance/ai-features" target="_blank" rel="noopener noreferrer">Google AI 搜索内容指南</a> · <a href="https://schema.org/Organization" target="_blank" rel="noopener noreferrer">Schema.org 企业信息</a></p></div>`;
}
function observation(p){const value=Object.fromEntries(['engine','date','question','market','cited','url','note'].map(k=>[k,String(p[k]||'').trim()]));if(!value.engine||!value.question||!/^\d{4}-\d{2}-\d{2}$/.test(value.date)||!['yes','no','unknown'].includes(value.cited))throw Error('请填写引擎、日期、提问内容和观察结果');if(value.url&&!/^https:\/\/[^\s<>]+$/i.test(value.url))throw Error('证据网址请使用 HTTPS');if(value.cited==='yes'&&!value.url&&!value.note)throw Error('请填写引用网址或证据说明');return value;}
function fromPrototype(s){const R=typeof module!=='undefined'&&module.exports?require('./rich-content.js'):root.LGARichContent;return {name:s.company.draft.name,product:s.company.draft.product,pages:s.site.blocks.filter(b=>!b.detailDeleted).map(b=>({id:b.id,title:b.title,html:b.rich?R.render(b.rich):b.body||'',summary:b.entry?.summary||''})),observations:s.site.geo?.observations||[]};}
function apply(s,type,p){if(type!=='geoSave')throw Error('未知 GEO 操作');const observations=s.site.geo?.observations||[];if(observations.length>=300)throw Error('观察记录最多 300 条，请先导出归档');s.site.geo={observations:[observation(p),...observations]};}
const api={inspect,render,observation,fromPrototype,apply};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.LGASiteGeo=api;
})(typeof globalThis!=='undefined'?globalThis:this);
